```go
package util

import (
	"context"
	"strconv"
)

// GetLimit は文字列から件数上限を得る。不正なら既定値10にする。
func GetLimit(raw string, ctx context.Context) (limit int, ok bool, err error) {
	limit, err = strconv.Atoi(raw)
	if err != nil {
		limit = 10
		err = nil
	} else {
		ok = true
	}
	return
}
```
